const test = require('node:test');
const assert = require('node:assert/strict');
const { daysBetween } = require('./daysbetween');

test('counts both end days', () => {
  assert.equal(daysBetween('2024-01-01', '2024-01-10'), 10);
});

test('a single day', () => {
  assert.equal(daysBetween('2024-05-05', '2024-05-05'), 1);
});

test('leap year february 28 to march 1', () => {
  assert.equal(daysBetween('2024-02-28', '2024-03-01'), 3);
});

test('non-leap year february 28 to march 1', () => {
  assert.equal(daysBetween('2023-02-28', '2023-03-01'), 2);
});

test('to date earlier than from throws RangeError', () => {
  assert.throws(() => {
    daysBetween('2024-01-10', '2024-01-01');
  }, RangeError);
});

test('invalid format throws RangeError', () => {
  assert.throws(() => {
    daysBetween('2024/01/01', '2024-01-02');
  }, RangeError);
  assert.throws(() => {
    daysBetween('24-01-01', '2024-01-02');
  }, RangeError);
});

test('non-existent day throws RangeError', () => {
  assert.throws(() => {
    daysBetween('2023-02-29', '2023-03-01');
  }, RangeError);
  assert.throws(() => {
    daysBetween('2024-04-31', '2024-05-01');
  }, RangeError);
});

test('non-string argument throws TypeError', () => {
  assert.throws(() => {
    daysBetween(20240101, '2024-01-02');
  }, TypeError);
  assert.throws(() => {
    daysBetween('2024-01-01', null);
  }, TypeError);
});
"}```

